H.background();
const r1 = P.r1, r2 = P.r2, r3 = P.r3, a = P.a;
const f = x => a * (x - r1) * (x - r2) * (x - r3);
const v = H.plot2d({ xMin: -7, xMax: 7, yMin: -12, yMax: 12 });
v.grid(); v.axes();
v.fn(f, { color: H.colors.accent, width: 3 });
v.dot(r1, 0, { r: 6, fill: H.colors.good });
v.dot(r2, 0, { r: 6, fill: H.colors.warn });
v.dot(r3, 0, { r: 6, fill: H.colors.violet });
const xs = 6 * Math.sin(t * 0.6);
v.dot(xs, f(xs), { r: 6, fill: H.colors.accent2 });
const sweep = -6 + ((t * 1.4) % 12);
const fy = f(sweep);
v.line(sweep, 0, sweep, fy, { color: H.colors.sub, width: 1, dash: [3, 3] });
H.text("Finding zeros:  f(x) = a(x−r₁)(x−r₂)(x−r₃)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("zeros at x = " + r1.toFixed(1) + ", " + r2.toFixed(1) + ", " + r3.toFixed(1) + "   (each crosses the x-axis)", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "r₁", color: H.colors.good }, { label: "r₂", color: H.colors.warn }, { label: "r₃", color: H.colors.violet }], H.W - 130, 28);
